#include <map>
#include <string>

int main() {
    std::map<int, std::string> m;
    m.insert({1, "one"});

    // 1. Value modification (OK)
    m[1] = "uno"; 

    auto it = m.begin();
    // it->first = 2; // ERROR: key is const

    // 2. Value modification via iterator (OK)
    it->second = "eins";

    // 3. Explicit value_type usage
    using MapVT = std::map<int, std::string>::value_type;
    m.insert(MapVT(2, "two"));
}
